from typing import List
import re

def separate_paren_groups(paren_string: str) -> List[str]:
    def find_groups(paren_string):
        result = []
        current_group = ''
        for char in paren_string:
            if char == '(':
                current_group += char
            elif char == ')':
                if current_group:
                    result.append(current_group[:-1])
                    current_group = ''
                else:
                    raise ValueError("Invalid parentheses string")

        if current_group:
            result.append(current_group)

        return result

    # Using re module for efficiency
    groups = re.findall(r'\(([^()]*)\)', paren_string)
    for group in groups:
        groups.append(find_groups(group[1]))

    return groups
