from collections import Counter

def is_happy(s):
    seen = Counter()

    for i in range(3):
        if s[i] in seen and seen[s[i]] > 1:
            return False
        seen[s[i]] += 1

    for i in range(len(s)-2):
        if seen[s[i]] > 0 and seen[s[i+1]] > 0 and seen[s[i+2]] > 0:
            if seen[s[i]], seen[s[i+1]], seen[s[i+2]] != 1, 1, 1:
                return False
        seen[s[i]] -= 1
        seen[s[i+3]] += 1
        if seen[s[i+3]] > 1:
            return False

    return len(s) >= 3
```

