def tri(n):
    def tribonacci(sequence, n):
        return list(islice(chain(cycle([1, 3]), sequence), n) if n < len(sequence) else tribonacci(tribonacci(sequence, n - 1) + tribonacci(sequence, n - 2) + [0], n)

