import re

def is_nested(string):
    def validate(s, index=0):
        if not s:
            return True
        if s[index] != "[" and s[index] != "]":
            return False
        opening, closing = s[index], s[index + 1] if index + 1 < len(s) else None
        if opening == "[" and (not closing or closing != "]"):
            return False
        return validate(re.sub(rf"{opening if opening else closing}[^[]*{(opening+"|"+closing) if opening and closing else ""}"]", "", s, index + 2) if index + 2 < len(s) else True

    return any(validate(string))
